CREATE TABLE IF NOT EXISTS businesses (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Africa/Johannesburg', currency TEXT NOT NULL DEFAULT 'ZAR', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, name TEXT NOT NULL, duration_minutes INTEGER NOT NULL, price_minor INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY (business_id) REFERENCES businesses(id));
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(business_id,email));
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, service_id TEXT NOT NULL, customer_id TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','confirmed','cancelled','completed')), payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','pending','paid','failed')), idempotency_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (business_id) REFERENCES businesses(id), FOREIGN KEY (service_id) REFERENCES services(id), FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS payment_intents (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL, provider TEXT NOT NULL, provider_reference TEXT, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('created','pending','paid','failed')), checkout_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS reminder_jobs (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','sms','whatsapp')), due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sent','failed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(booking_id,channel,due_at), FOREIGN KEY (booking_id) REFERENCES bookings(id));
CREATE INDEX IF NOT EXISTS idx_v2_bookings_service_time ON bookings(service_id, starts_at, ends_at);
CREATE INDEX IF NOT EXISTS idx_v2_bookings_business_time ON bookings(business_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_v2_reminders_due ON reminder_jobs(status, due_at);
